    "emp": "Société Générale",
    "title": "Analyste ALM Pilotage et Trésorerie",
    "sector": "Banque de réseau",
    "famille": "Contrôle de gestion & Trésorerie",
    "volet": "cdi-cdd",
    "loc": "Boulogne-Billancourt",
